    int u, v;
    T cap, flow, cost;
};

struct CostFlow {
    int n, m, s, t;
    vector<int> adj[maxn];
    vector<Edge> edges;
    T dist[maxn];
    bool inQ[maxn];
    int parent[maxn];
    T minCap[maxn];

    explicit CostFlow(int nodes) : n(nodes) {}

    void add_edge(int u, int v, T capacity, T cost) {
        edges.push_back({u, v, capacity, 0, cost});
        edges.push_back({v, u, 0, 0, -cost});
        m = (int)edges.size();
        adj[u].push_back(m - 2);
        adj[v].push_back(m - 1);
    }

    bool find_augmenting_path(T &flow, T &cost) {
        for (int i = 0; i < n; ++i) dist[i] = INF;
        memset(inQ, 0, sizeof(inQ));
        dist[s] = 0; inQ[s] = true; parent[s] = -1; minCap[s] = INF;

        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inQ[u] = false;
            for (int i : adj[u]) {
                Edge &e = edges[i];
                if (e.cap > e.flow && dist[e.v] > dist[u] + e.cost) {
                    dist[e.v] = dist[u] + e.cost;
                    parent[e.v] = i;
                    minCap[e.v] = min(minCap[u], e.cap - e.flow);
                    if (!inQ[e.v]) {
                        q.push(e.v);
                        inQ[e.v] = true;
                    }
                }
            }
        }
        if (dist[t] == INF) return false;
        flow = minCap[t];
        cost = dist[t];
        int u = t;
        while (u != s) {
            edges[parent[u]].flow += flow;
            edges[parent[u] ^ 1].flow -= flow;
            u = edges[parent[u]].u;
        }
        return true;
    }

    pair<T, T> solve(int s, int t) {
        this->s = s; this->t = t;
        T totalFlow = 0, totalCost = 0;
        T f = 0, d = 0;
        while (find_augmenting_path(f, d)) {
            totalFlow += f;
            totalCost += f * d;
        }
        return make_pair(totalFlow, totalCost);
    }
};

int main() {
    int n, m, k, C, D;
    cin >> n >> m >> k >> C >> D;

    CostFlow solver(n * K + 2);
    int source = n * K, sink = n * K + 1;

    for (int i = 0; i < K; ++i)
