import java.util.*;
import java.io.*;

public class Main {
    static final int maxn = 5005;
    static final int K = 100;
    static final int INF = 1000000007;

    static class Edge {
        int u, v;
        int cap, flow, cost;

        Edge(int u, int v, int cap, int flow, int cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static class CostFlow {
        int n, m, s, t;
        List<Integer>[] adj;
        List<Edge> edges;
        int[] parent;
        int[] minCap;
        long[] dist;
        boolean[] inQ;

        @SuppressWarnings("unchecked")
        public CostFlow(int nodes) {
            this.n = nodes;
            adj = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }
            edges = new ArrayList<>();
            parent = new int[n];
            minCap = new int[n];
            dist = new long[n];
            inQ = new boolean[n];
        }

        void add_edge(int u, int v, int cap, int cost) {
            edges.add(new Edge(u, v, cap, 0, cost));
            edges.add(new Edge(v, u, 0, 0, -cost));
            int mIndex = edges.size() - 2;
            adj[u].add(mIndex);
            adj[v].add(mIndex + 1);
        }

        boolean find_augmenting_path(long[] flowCost) {
            Arrays.fill(dist, Long.MAX_VALUE);
            Arrays.fill(inQ, false);
            Arrays.fill(parent, -1);
            Arrays.fill(minCap, 0);
            dist[s] = 0;
            inQ[s] = true;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                inQ[u] = false;
                for (int i : adj[u]) {
                    Edge e = edges.get(i);
                    if (e.cap > e.flow && dist[e.v] > dist[u] + e.cost) {
                        dist[e.v] = dist[u] + e.cost;
                        parent[e.v] = i;
                        minCap[e.v] = (u == s) ? e.cap - e.flow : Math.min(minCap[u], e.cap - e.flow);
                        if (!inQ[e.v]) {
                            q.offer(e.v);
                            inQ[e.v] = true;
                        }
                    }
                }
            }
            if (dist[t] == Long.MAX_VALUE) {
                return false;
            }
            long flow = minCap[t];
            long cost = dist[t];
            int u = t;
            while (u != s) {
                int i = parent[u];
                edges.get(i).flow += flow;
                edges.get(i ^ 1).flow -= flow;
                u = edges.get(i).u;
            }
            flowCost[0] += flow;
            flowCost[1] += flow * cost;
            return true;
        }

        long[] solve(int s, int t) {
            this.s = s;
            this.t = t;
            long totalFlow = 0;
            long totalCost = 0;
            long[] flowCost = new long[2];
            while (find_augmenting_path(flowCost)) {
                totalFlow += flowCost[0];
                totalCost += flowCost[1];
            }
            return new long[]{totalFlow, totalCost};
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(br.readLine());

        int totalNodes = n * K + 2;
        int source = n * K;
        int sink = n * K + 1;

        CostFlow solver = new CostFlow(totalNodes);

        for (int i = 0; i < K; i++) {
            solver.add_edge(i, sink, k, C * i);
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(st.nextToken()) - 1;
            solver.add_edge(source, x * K, 1, 0);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < K; j++) {
                solver.add_edge(i * K + j - 1, i * K + j, k, 0);
            }
        }

        for (int _ = 0; _ < m; _++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int j = 1, cc = D; j <= k; j++, cc += 2 * D) {
                int a = u * K + j - 1;
                int b = v * K + j;
                int c = v * K + j - 1;
                int d = u * K + j;
                solver.add_edge(a, b, 1, cc);
                solver.add_edge(c, d, 1, cc);
            }
        }

        long[] res = solver.solve(source, sink);
        System.out.println(res[1]);
    }
}
